window.jalaliDatepicker = (function () {
    "use strict";
    var config = { hideAfterChange: true };
    var currentYear = 1403, currentMonth = 1;
    var activeInput = null, container = null;

    function gregorianToJalali(gy, gm, gd) {
        var g_d_m = [0, 31, (gy % 4 == 0 && gy % 100 != 0) || gy % 400 == 0 ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
        var jy = (gy <= 1600) ? 0 : 979;
        gy -= (gy <= 1600) ? 621 : 1600;
        var gy2 = (gm > 2) ? (gy + 1) : gy;
        var days = (365 * gy) + (parseInt((gy2 + 3) / 4)) - (parseInt((gy2 + 99) / 100)) + (parseInt((gy2 + 399) / 400)) - 80 + gd;
        for (var i = 0; i < gm; ++i) days += g_d_m[i];
        jy += 33 * parseInt(days / 12053);
        days %= 12053;
        jy += 4 * parseInt(days / 1461);
        days %= 1461;
        jy += parseInt((days - 1) / 365);
        if (days > 0) days = (days - 1) % 365;
        var jm = (days < 186) ? 1 + parseInt(days / 31) : 7 + parseInt((days - 186) / 30);
        var jd = 1 + ((days < 186) ? (days % 31) : ((days - 186) % 30));
        return [jy, jm, jd];
    }

    function jalaliToGregorian(jy, jm, jd) {
        var gy = (jy <= 979) ? 621 : 1600;
        jy -= (jy <= 979) ? 0 : 979;
        var days = (365 * jy) + (parseInt(jy / 33) * 8) + parseInt(((jy % 33) + 3) / 4) + 78 + jd + ((jm < 7) ? (jm - 1) * 31 : ((jm - 7) * 30) + 186);
        gy += 400 * parseInt(days / 146097);
        days %= 146097;
        if (days > 36524) {
            gy += 100 * parseInt(--days / 36524);
            days %= 36524;
            if (days >= 365) days++;
        }
        gy += 4 * parseInt(days / 1461);
        days %= 1461;
        gy += parseInt((days - 1) / 365);
        if (days > 0) days = (days - 1) % 365;
        var sal_a = [0, 31, ((gy % 4 == 0 && gy % 100 != 0) || gy % 400 == 0) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
        var gm = 0;
        for (gm = 0; days >= sal_a[gm]; gm++) days -= sal_a[gm];
        return [gy, gm, days + 1];
    }

    function pad(n) { return n < 10 ? "0" + n : n; }

    function getTodayJalali() {
        var d = new Date();
        return gregorianToJalali(d.getFullYear(), d.getMonth() + 1, d.getDate());
    }

    function render() {
        if (!container) return;
        var months = ["فروردین", "اردیبهشت", "خرداد", "تیر", "مرداد", "شهریور", "مهر", "آبان", "آذر", "دی", "بهمن", "اسفند"];
        var html = '<header><div><select id="jdp-month">';
        months.forEach(function (m, idx) {
            html += '<option value="' + (idx + 1) + '" ' + (idx + 1 === currentMonth ? 'selected' : '') + '>' + m + '</option>';
        });
        html += '</select><select id="jdp-year">';
        for (var y = currentYear - 30; y <= currentYear + 30; y++) {
            html += '<option value="' + y + '" ' + (y === currentYear ? 'selected' : '') + '>' + y + '</option>';
        }
        html += '</select></div><div><span class="jdp-btn-prev">&gt;</span><span class="jdp-btn-next">&lt;</span></div></header>';
        html += '<table><thead><tr><th>ش</th><th>ی</th><th>د</th><th>س</th><th>چ</th><th>پ</th><th>ج</th></tr></thead><tbody>';

        var gFirst = jalaliToGregorian(currentYear, currentMonth, 1);
        var firstDayOfWeek = (new Date(gFirst[0], gFirst[1] - 1, gFirst[2]).getDay() + 1) % 7;
        var daysInMonth = currentMonth <= 6 ? 31 : currentMonth <= 11 ? 30 : 29;

        html += '<tr>';
        for (var i = 0; i < firstDayOfWeek; i++) html += '<td></td>';
        for (var day = 1; day <= daysInMonth; day++) {
            if ((firstDayOfWeek + day - 1) % 7 === 0 && day !== 1) html += '</tr><tr>';
            var selected = (activeInput && activeInput.value === currentYear + "/" + pad(currentMonth) + "/" + pad(day)) ? 'jdp-day-selected' : '';
            html += '<td class="' + selected + '"><div>' + day + '</div></td>';
        }
        html += '</tr></tbody></table>';
        html += '<footer><button type="button" id="jdp-today">امروز</button><button type="button" id="jdp-close">بستن</button></footer>';

        container.innerHTML = html;
        bindEvents();
    }

    function selectDay(day) {
        if (!activeInput) return;
        activeInput.value = currentYear + "/" + pad(currentMonth) + "/" + pad(day);
        activeInput.dispatchEvent(new Event("change"));
        if (config.hideAfterChange) hide();
    }

    function bindEvents() {
        container.querySelector("#jdp-month").addEventListener("change", function (e) {
            currentMonth = parseInt(e.target.value);
            render();
        });
        container.querySelector("#jdp-year").addEventListener("change", function (e) {
            currentYear = parseInt(e.target.value);
            render();
        });
        container.querySelector(".jdp-btn-prev").addEventListener("click", function () {
            if (currentMonth === 1) { currentMonth = 12; currentYear--; } else { currentMonth--; }
            render();
        });
        container.querySelector(".jdp-btn-next").addEventListener("click", function () {
            if (currentMonth === 12) { currentMonth = 1; currentYear++; } else { currentMonth++; }
            render();
        });
        container.querySelector("#jdp-today").addEventListener("click", function () {
            var today = getTodayJalali();
            currentYear = today[0];
            currentMonth = today[1];
            selectDay(today[2]);
        });
        container.querySelector("#jdp-close").addEventListener("click", hide);

        var days = container.querySelectorAll("td div");
        days.forEach(function (el) {
            el.addEventListener("click", function () {
                if (el.innerText) selectDay(parseInt(el.innerText));
            });
        });
    }

    function show(target) {
        activeInput = target;
        if (!container) {
            container = document.createElement("jdp-container");
            container.id = "jdp-container";
            document.body.appendChild(container);
        }
        var rect = activeInput.getBoundingClientRect();
        container.style.top = (rect.bottom + window.scrollY + 4) + "px";
        container.style.left = (rect.left + window.scrollX) + "px";

        var today = getTodayJalali();
        currentYear = today[0];
        currentMonth = today[1];
        render();
        container.style.display = "block";
    }

    function hide() {
        if (container) container.style.display = "none";
        activeInput = null;
    }

    return {
        startWatch: function (opts) {
            if (opts) Object.assign(config, opts);
            document.addEventListener("click", function (e) {
                var target = e.target.closest("[data-jdp]");
                if (target) {
                    show(target);
                } else if (container && !container.contains(e.target)) {
                    hide();
                }
            });
        },
        hide: hide
    };
})();
